def query_collection(collection_name, query_vector, filter=None, limit=None, offset=None, with_payload=None, with_vector=None, score_threshold=None, request_source=None, wait=None, **_extra):
    import json, os, datetime, math, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0415000" if __import__("os").path.isdir("./environment_mix/0415000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    start_dt = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        # Match store-ish convention: qdrant_qry / qdrant_qres
        return f"{prefix}_{uuid.uuid7().hex}" if hasattr(uuid, "uuid7") else f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{os.urandom(6).hex()}"

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log_request(status, error_code=None, query_request_id=None, collection_id=None):
        latency_ms = int((datetime.datetime.utcnow() - start_dt).total_seconds() * 1000)
        row = {
            "id": _gen_id("req"),
            "endpoint": "query_collection",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        if query_request_id is not None:
            row["query_request_id"] = query_request_id
        if collection_id is not None:
            row["collection_id"] = collection_id
        logs = _load_logs()
        logs.append(row)
        _save("request_logs.json", logs)

    def _finite_num(x):
        if isinstance(x, bool):
            return False
        if not isinstance(x, (int, float)):
            return False
        if isinstance(x, float) and (math.isnan(x) or math.isinf(x)):
            return False
        return True

    def _score(vec, qv, metric):
        # Higher is better.
        if metric == "dot":
            return float(sum(a * b for a, b in zip(vec, qv)))
        if metric == "cosine":
            dot = float(sum(a * b for a, b in zip(vec, qv)))
            na = math.sqrt(sum(a * a for a in vec))
            nb = math.sqrt(sum(b * b for b in qv))
            if na == 0.0 or nb == 0.0:
                return 0.0
            return dot / (na * nb)
        if metric == "euclid":
            # convert distance to similarity
            dist = math.sqrt(sum((a - b) ** 2 for a, b in zip(vec, qv)))
            return 1.0 / (1.0 + dist)
        if metric == "manhattan":
            dist = sum(abs(a - b) for a, b in zip(vec, qv))
            return 1.0 / (1.0 + float(dist))
        # fallback
        return float(sum(a * b for a, b in zip(vec, qv)))

    def _match_filter(payload, flt):
        # Minimal Qdrant-like filter support.
        # Accept {}, None => match all.
        # Support keys: must (list), should (list), must_not (list)
        # Each condition: {"key": "...", "match": {"value": ...}} or {"key":"...", "match":{"any":[...]}}
        if flt is None:
            return True
        if not isinstance(flt, dict):
            return True  # relax: treat bad filter as no-op rather than hard fail (tool schema allows object; callers might pass {})
        if flt == {}:
            return True
        if payload is None or not isinstance(payload, dict):
            payload = {}

        def eval_cond(cond):
            if not isinstance(cond, dict):
                return True
            key = cond.get("key")
            m = cond.get("match")
            if not isinstance(key, str) or not key:
                return True
            if not isinstance(m, dict):
                return True
            if "value" in m:
                return payload.get(key) == m.get("value")
            if "any" in m and isinstance(m.get("any"), list):
                return payload.get(key) in m.get("any")
            return True

        must = flt.get("must")
        should = flt.get("should")
        must_not = flt.get("must_not")

        if isinstance(must, list):
            for c in must:
                if not eval_cond(c):
                    return False
        if isinstance(must_not, list):
            for c in must_not:
                if eval_cond(c):
                    return False
        if isinstance(should, list) and len(should) > 0:
            ok = any(eval_cond(c) for c in should)
            if not ok:
                return False
        return True

    # Validate inputs
    if not isinstance(collection_name, str) or not collection_name.strip():
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_name must be a non-empty string")
    if not isinstance(query_vector, list):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query_vector must be an array of numbers")
    # Relax vector validation: if elements not finite, reject; but don't enforce length (audit requires relaxation).
    for i, v in enumerate(query_vector):
        if not _finite_num(v):
            _log_request("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"query_vector[{i}] must be a finite number", index=i)
    if limit is None:
        limit = 10
    if offset is None:
        offset = 0
    if with_payload is None:
        with_payload = True
    if with_vector is None:
        with_vector = False
    if wait is None:
        wait = True

    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 1000:
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer within [1, 1000]", limit=limit)
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0", offset=offset)
    if not isinstance(with_payload, bool):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "with_payload must be a boolean")
    if not isinstance(with_vector, bool):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "with_vector must be a boolean")
    if score_threshold is not None and not _finite_num(score_threshold):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "score_threshold must be a finite number when provided")
    if request_source is not None and (not isinstance(request_source, str) or not request_source.strip()):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "request_source must be a non-empty string when provided")
    if filter is not None and not isinstance(filter, dict):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filter must be an object when provided")
    if not isinstance(wait, bool):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "wait must be a boolean")

    cols = _load("collections.json")
    if not isinstance(cols, list):
        cols = []
    col = next((r for r in cols if isinstance(r, dict) and r.get("name") == collection_name.strip() and r.get("status") != "deleted"), None)
    if not col:
        _log_request("failed", "NOT_FOUND")
        return _err("NOT_FOUND", "collection not found", collection_name=collection_name.strip())

    if col.get("status") in ("creating", "deleting", "deleted"):
        _log_request("failed", "CONFLICT", collection_id=col.get("id"))
        return _err("CONFLICT", "collection is not available for querying in its current status", status=col.get("status"), collection_name=collection_name.strip())

    # Create query_requests row and transition queued->running->...
    qreqs = _load("query_requests.json")
    if not isinstance(qreqs, list):
        qreqs = []
    qres = _load("query_results.json")
    if not isinstance(qres, list):
        qres = []

    qid = _gen_id("qdrant_qry")
    qrow = {
        "id": qid,
        "collection_id": col.get("id"),
        "status": "queued",
        "query_vector": query_vector,
        "filter": filter,
        "limit": int(limit),
        "offset": int(offset),
        "with_payload": bool(with_payload),
        "with_vector": bool(with_vector),
        "score_threshold": score_threshold,
        "request_source": request_source,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    qreqs.append(qrow)
    _save("query_requests.json", qreqs)

    # If async, leave queued and return handle
    if wait is False:
        _log_request("succeeded", None, query_request_id=qid, collection_id=col.get("id"))
        return {
            "result": {
                "request_id": qid,
                "status": "queued",
                "collection_name": col.get("name"),
            }
        }

    # running
    for r in qreqs:
        if isinstance(r, dict) and r.get("id") == qid:
            r["status"] = "running"
            r["updated_at"] = _now_iso()
            break
    _save("query_requests.json", qreqs)

    t0 = datetime.datetime.utcnow()
    try:
        pts = _load("points.json")
        if not isinstance(pts, list):
            pts = []

        metric = col.get("distance_metric") or "cosine"
        # Score candidates; relax vector-length mismatch by scoring on overlapping dims.
        candidates = []
        for p in pts:
            if not isinstance(p, dict):
                continue
            if p.get("collection_id") != col.get("id"):
                continue
            if p.get("status") != "active":
                continue
            vec = p.get("vector")
            if not isinstance(vec, list) or len(vec) == 0:
                continue
            # ensure numeric finites for stored vectors; skip bad rows
            ok = True
            for v in vec:
                if not _finite_num(v):
                    ok = False
                    break
            if not ok:
                continue

            if not _match_filter(p.get("payload"), filter):
                continue

            # Use common length for zip; if no overlap, score 0
            dim = min(len(vec), len(query_vector))
            if dim <= 0:
                sc = 0.0
            else:
                sc = _score(vec[:dim], query_vector[:dim], metric)
            if score_threshold is not None and sc < float(score_threshold):
                continue

            candidates.append((sc, p))

        # Sort best-first
        candidates.sort(key=lambda x: x[0], reverse=True)

        # Apply offset/limit
        sliced = candidates[offset: offset + limit] if offset < len(candidates) else []

        # Remove any previous results for this request (shouldn't exist, but be safe/idempotent)
        qres = [r for r in qres if not (isinstance(r, dict) and r.get("query_request_id") == qid)]
        created_at = _now_iso()
        out_matches = []
        rank = 1
        for sc, p in sliced:
            rr = {
                "id": _gen_id("qdrant_qres"),
                "query_request_id": qid,
                "point_id": p.get("id"),
                "rank": rank,
                "score": float(sc),
                "returned_payload": (p.get("payload") if with_payload else None),
                "returned_vector": (p.get("vector") if with_vector else None),
                "created_at": created_at,
                "updated_at": created_at,
            }
            qres.append(rr)
            out_matches.append({
                "id": p.get("external_point_id"),
                "point_id": p.get("id"),
                "score": float(sc),
                "payload": (p.get("payload") if with_payload else None),
                "vector": (p.get("vector") if with_vector else None),
            })
            rank += 1

        _save("query_results.json", qres)

        dur_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        for r in qreqs:
            if isinstance(r, dict) and r.get("id") == qid:
                r["status"] = "succeeded"
                r["duration_ms"] = max(0, dur_ms)
                r["error_message"] = None
                r["updated_at"] = _now_iso()
                break
        _save("query_requests.json", qreqs)

        _log_request("succeeded", None, query_request_id=qid, collection_id=col.get("id"))
        return {
            "result": {
                "request_id": qid,
                "status": "succeeded",
                "collection_name": col.get("name"),
                "matches": out_matches,
                "limit": limit,
                "offset": offset,
                "count": len(out_matches),
            }
        }
    except Exception as e:
        dur_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        # Mark failed
        for r in qreqs:
            if isinstance(r, dict) and r.get("id") == qid:
                r["status"] = "failed"
                r["duration_ms"] = max(0, dur_ms)
                r["error_message"] = str(e)[:500]
                r["updated_at"] = _now_iso()
                break
        _save("query_requests.json", qreqs)
        _log_request("failed", "VALIDATION_ERROR", query_request_id=qid, collection_id=col.get("id"))
        return _err("VALIDATION_ERROR", "query execution failed", query_request_id=qid, error_message=str(e)[:500])

def list_collections(limit=None, cursor=None, status=None, sort=None, order=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0415000" if __import__("os").path.isdir("./environment_mix/0415000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_dt = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{os.urandom(6).hex()}"

    def _log_request(status_str, error_code=None):
        latency_ms = int((datetime.datetime.utcnow() - start_dt).total_seconds() * 1000)
        row = {
            "id": _gen_id("req"),
            "endpoint": "list_collections",
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer within [1, 1000]")

    if cursor is not None and not isinstance(cursor, str):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided")

    allowed_status = ["creating", "green", "optimizing", "degraded", "deleting", "deleted"]
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of allowed values", allowed=allowed_status)

    allowed_sort = ["created_at", "updated_at", "name"]
    if sort is None:
        sort = "name"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of allowed values", allowed=allowed_sort)

    allowed_order = ["asc", "desc"]
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in allowed_order:
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order must be one of allowed values", allowed=allowed_order)

    cols = _load("collections.json")
    if not isinstance(cols, list):
        cols = []

    rows = [c for c in cols if isinstance(c, dict) and c.get("status") != "deleted"]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]

    # Stable sort
    reverse = (order == "desc")
    def _key(c):
        v = c.get(sort)
        if v is None:
            return ""
        return v
    rows.sort(key=_key, reverse=reverse)

    # Cursor is the last seen collection id (not an integer index)
    start_index = 0
    if cursor:
        ids = [r.get("id") for r in rows]
        if cursor in ids:
            start_index = ids.index(cursor) + 1
        else:
            # Relaxed: do not error; start from beginning (cursor may be from different filter/sort)
            start_index = 0

    page = rows[start_index:start_index + limit]
    next_cursor = None
    has_more = start_index + limit < len(rows)
    if has_more and page:
        next_cursor = page[-1].get("id")

    result_rows = []
    for c in page:
        result_rows.append(
            {
                "name": c.get("name"),
                "status": c.get("status"),
                "created_at": c.get("created_at"),
                "updated_at": c.get("updated_at"),
            }
        )

    _log_request("succeeded", None)
    return {
        "result": {
            "collections": result_rows,
            "total": len(rows),
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        }
    }

def collection_info(collection_name, include_config=None, include_stats=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0415000" if __import__("os").path.isdir("./environment_mix/0415000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(collection_name, str) or not collection_name.strip():
        return _err("VALIDATION_ERROR", "collection_name must be a non-empty string")

    if include_config is None:
        include_config = True
    if include_stats is None:
        include_stats = True
    if not isinstance(include_config, bool):
        return _err("VALIDATION_ERROR", "include_config must be a boolean")
    if not isinstance(include_stats, bool):
        return _err("VALIDATION_ERROR", "include_stats must be a boolean")

    cols = _load("collections.json")
    col = None
    for c in cols:
        if c.get("name") == collection_name and c.get("status") != "deleted":
            col = c
            break
    if not col:
        return _err("NOT_FOUND", "collection not found", collection_name=collection_name)

    info = {
        "id": col.get("id"),
        "name": col.get("name"),
        "status": col.get("status"),
        "created_at": col.get("created_at"),
        "updated_at": col.get("updated_at"),
    }

    if include_config:
        info["config"] = {
            "vector_size": col.get("vector_size"),
            "distance_metric": col.get("distance_metric"),
            "shard_count": col.get("shard_count"),
            "replication_factor": col.get("replication_factor"),
            "on_disk_payload": col.get("on_disk_payload"),
            "hnsw_config": col.get("hnsw_config"),
            "optimizer_config": col.get("optimizer_config"),
        }

    if include_stats:
        info["stats"] = {
            "points_count": col.get("points_count"),
            "vectors_count": col.get("vectors_count"),
            "segments_count": col.get("segments_count"),
            "last_optimized_at": col.get("last_optimized_at"),
        }

    return {"result": info}

def create_collection(collection_name, vector_size, distance_metric, replication_factor=None, shard_count=None, on_disk_payload=None, hnsw_config=None, optimizer_config=None, **_extra):
    import json, os, datetime, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0415000" if __import__("os").path.isdir("./environment_mix/0415000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start_dt = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        # Qdrant-like id convention seen in store examples: qdrant_col_<something>
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_request(status, error_code=None, collection_id=None):
        # No declared request-log collection in schema; still keep vendor-like observability if file exists.
        latency_ms = int((datetime.datetime.utcnow() - start_dt).total_seconds() * 1000)
        row = {
            "id": _gen_id("qdrant_req"),
            "endpoint": "create_collection",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        if collection_id is not None:
            row["collection_id"] = collection_id
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate required
    if not isinstance(collection_name, str) or not collection_name.strip():
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_name must be a non-empty string")
    collection_name = collection_name.strip()

    if not isinstance(vector_size, int) or isinstance(vector_size, bool) or vector_size < 1:
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "vector_size must be an integer >= 1")

    if not isinstance(distance_metric, str) or distance_metric not in ("cosine", "dot", "euclid"):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "distance_metric must be one of: cosine, dot, euclid", allowed=["cosine", "dot", "euclid"])

    # Validate optionals / defaults
    if replication_factor is None:
        replication_factor = 1
    if shard_count is None:
        shard_count = 1
    if on_disk_payload is None:
        on_disk_payload = False
    if hnsw_config is None:
        hnsw_config = {}
    if optimizer_config is None:
        optimizer_config = {}

    if not isinstance(replication_factor, int) or isinstance(replication_factor, bool) or replication_factor < 1:
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "replication_factor must be an integer >= 1")
    if not isinstance(shard_count, int) or isinstance(shard_count, bool) or shard_count < 1:
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "shard_count must be an integer >= 1")
    if not isinstance(on_disk_payload, bool):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "on_disk_payload must be a boolean")
    if not isinstance(hnsw_config, dict):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hnsw_config must be an object")
    if not isinstance(optimizer_config, dict):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "optimizer_config must be an object")

    cols = _load("collections.json")
    if not isinstance(cols, list):
        cols = []

    # CONFLICT only if non-deleted collection with same name exists
    for r in cols:
        if isinstance(r, dict) and r.get("name") == collection_name and r.get("status") != "deleted":
            _log_request("failed", "CONFLICT", collection_id=r.get("id"))
            return _err("CONFLICT", "collection with this name already exists", collection_name=collection_name)

    now = _now_iso()
    col_id = _gen_id("qdrant_col")

    new_row = {
        "id": col_id,
        "name": collection_name,
        "status": "creating",
        "vector_size": vector_size,
        "distance_metric": distance_metric,
