def delete_collection(collection_name, wait=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0415000" if __import__("os").path.isdir("./environment_mix/0415000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()
    endpoint = "delete_collection"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)
        row = {
            "id": f"req_{int(datetime.datetime.utcnow().timestamp()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now()
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(collection_name, str) or not collection_name.strip():
        _log("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_name must be a non-empty string")
    if wait is not None and not isinstance(wait, bool):
        _log("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "wait must be a boolean")

    cols = _load("collections.json")
    if not isinstance(cols, list):
        cols = []

    col = None
    for r in cols:
        if isinstance(r, dict) and r.get("name") == collection_name:
            col = r
            break

    if not col or col.get("status") == "deleted":
        _log("failed", "NOT_FOUND")
        return _err("NOT_FOUND", "Collection not found or already deleted")

    # Lifecycle transitions
    transitions = {
        "creating": ["green", "degraded", "deleting"],
        "green": ["optimizing", "degraded", "deleting"],
        "optimizing": ["green", "degraded", "deleting"],
        "degraded": ["green", "deleting"],
        "deleting": ["deleted"],
        "deleted": []
    }

    cur = col.get("status")
    if cur != "deleting":
        if cur not in transitions or "deleting" not in transitions.get(cur, []):
            _log("failed", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition collection from {cur} to deleting")
        col["status"] = "deleting"
        col["updated_at"] = _now()
        _save("collections.json", cols)

    if wait:
        # Simulate eventual deletion by completing transition and marking deleted.
        # Also mark all points in that collection as deleted (as a consequence).
        # (Real Qdrant would drop the storage; here we retain rows but status changes for observability.)
        deadline = time.time() + 5.0  # bounded wait to avoid hanging
        while time.time() < deadline:
            # complete transition
            cols = _load("collections.json")
            if not isinstance(cols, list):
                cols = []
            col2 = None
            for r in cols:
                if isinstance(r, dict) and r.get("name") == collection_name:
                    col2 = r
                    break
            if not col2:
                break
            if col2.get("status") == "deleted":
                col = col2
                break
            if col2.get("status") == "deleting":
                col2["status"] = "deleted"
                col2["updated_at"] = _now()
                _save("collections.json", cols)

                # cascade point status to deleted and refresh cached counts
                pts = _load("points.json")
                if not isinstance(pts, list):
                    pts = []
                changed = False
                for p in pts:
                    if isinstance(p, dict) and p.get("collection_id") == col2.get("id") and p.get("status") == "active":
                        p["status"] = "deleted"
                        p["updated_at"] = _now()
                        p["version"] = int(p.get("version") or 0) + 1
                        changed = True
                if changed:
                    _save("points.json", pts)
                # cached stats
                active_count = 0
                for p in pts:
                    if isinstance(p, dict) and p.get("collection_id") == col2.get("id") and p.get("status") == "active":
                        active_count += 1
                col2["points_count"] = active_count
                col2["vectors_count"] = active_count
                col2["updated_at"] = _now()
                _save("collections.json", cols)

                col = col2
                break
            time.sleep(0.05)

    _log("succeeded")
    return {
        "result": {
            "name": col.get("name"),
            "status": col.get("status"),
            "waited": bool(wait),
            "deleted": col.get("status") == "deleted",
            "updated_at": col.get("updated_at"),
        }
    }

def upsert_points(collection_name, points, wait=None, **_extra):
    import json, os, datetime, uuid, hashlib, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0415000" if __import__("os").path.isdir("./environment_mix/0415000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start_dt = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_request(status, error_code=None, collection_id=None):
        latency_ms = int((datetime.datetime.utcnow() - start_dt).total_seconds() * 1000)
        row = {
            "id": _gen_id("qdrant_req"),
            "endpoint": "upsert_points",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        if collection_id is not None:
            row["collection_id"] = collection_id
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _finite_num(x):
        if isinstance(x, bool):
            return False
        if not isinstance(x, (int, float)):
            return False
        if isinstance(x, float) and (math.isnan(x) or math.isinf(x)):
            return False
        return True

    # Validate inputs
    if not isinstance(collection_name, str) or not collection_name.strip():
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_name must be a non-empty string")
    collection_name = collection_name.strip()

    if wait is None:
        wait = True
    if not isinstance(wait, bool):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "wait must be a boolean")

    if not isinstance(points, list) or len(points) < 1:
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "points must be a non-empty array")

    cols = _load("collections.json")
    if not isinstance(cols, list):
        cols = []
    col = next((r for r in cols if isinstance(r, dict) and r.get("name") == collection_name), None)
    if not col or col.get("status") == "deleted":
        _log_request("failed", "NOT_FOUND")
        return _err("NOT_FOUND", "collection not found", collection_name=collection_name)

    if col.get("status") in ("creating", "deleting"):
        _log_request("failed", "CONFLICT", collection_id=col.get("id"))
        return _err("CONFLICT", "collection is not ready for writes", status=col.get("status"), collection_name=collection_name)

    vector_size = col.get("vector_size")
    if not isinstance(vector_size, int) or vector_size < 1:
        _log_request("failed", "CONFLICT", collection_id=col.get("id"))
        return _err("CONFLICT", "collection has invalid vector_size", collection_id=col.get("id"))

    # Load points table
    pts = _load("points.json")
    if not isinstance(pts, list):
        pts = []

    # Index existing points for fast lookup (within the collection)
    by_internal = {}
    by_external = {}
    for p in pts:
        if not isinstance(p, dict):
            continue
        if p.get("collection_id") != col.get("id"):
            continue
        pid = p.get("id")
        if isinstance(pid, str):
            by_internal[pid] = p
        ext = p.get("external_point_id")
        if isinstance(ext, str):
            by_external[ext] = p

    # Validate all points first (no partial writes on validation failure)
    normalized = []
    for i, p in enumerate(points):
        if not isinstance(p, dict):
            _log_request("failed", "VALIDATION_ERROR", collection_id=col.get("id"))
            return _err("VALIDATION_ERROR", f"points[{i}] must be an object")

        allowed_keys = {"id", "external_point_id", "vector", "payload"}
        for k in p.keys():
            if k not in allowed_keys:
                _log_request("failed", "VALIDATION_ERROR", collection_id=col.get("id"))
                return _err("VALIDATION_ERROR", f"points[{i}] has unknown field '{k}'")

        if "vector" not in p:
            _log_request("failed", "VALIDATION_ERROR", collection_id=col.get("id"))
            return _err("VALIDATION_ERROR", f"points[{i}].vector is required")

        vec = p.get("vector")
        if not isinstance(vec, list):
            _log_request("failed", "VALIDATION_ERROR", collection_id=col.get("id"))
            return _err("VALIDATION_ERROR", f"points[{i}].vector must be an array of numbers")
        if len(vec) != vector_size:
            _log_request("failed", "VALIDATION_ERROR", collection_id=col.get("id"))
            return _err("VALIDATION_ERROR", f"points[{i}].vector length must equal collection vector_size ({vector_size})", expected=vector_size, got=len(vec))
        for j, x in enumerate(vec):
            if not _finite_num(x):
                _log_request("failed", "VALIDATION_ERROR", collection_id=col.get("id"))
                return _err("VALIDATION_ERROR", f"points[{i}].vector[{j}] must be a finite number")

        pid = p.get("id")
        if pid is not None and (not isinstance(pid, str) or not pid.strip()):
            _log_request("failed", "VALIDATION_ERROR", collection_id=col.get("id"))
            return _err("VALIDATION_ERROR", f"points[{i}].id must be a non-empty string when provided")
        pid = pid.strip() if isinstance(pid, str) else None

        ext = p.get("external_point_id")
        if ext is not None and (not isinstance(ext, str) or not ext.strip()):
            _log_request("failed", "VALIDATION_ERROR", collection_id=col.get("id"))
            return _err("VALIDATION_ERROR", f"points[{i}].external_point_id must be a non-empty string when provided")
        ext = ext.strip() if isinstance(ext, str) else None

        payload = p.get("payload") if "payload" in p else None
        if payload is not None and not isinstance(payload, dict):
            _log_request("failed", "VALIDATION_ERROR", collection_id=col.get("id"))
            return _err("VALIDATION_ERROR", f"points[{i}].payload must be an object when provided")

        normalized.append({"id": pid, "external_point_id": ext, "vector": vec, "payload": payload})

    # Apply upserts
    now = _now_iso()
    upserted = 0

    def _hash_payload(pl):
        if pl is None:
            return None
        try:
            b = json.dumps(pl, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        except Exception:
            return None
        return hashlib.sha256(b).hexdigest()

    touched_active_delta = 0  # for cached stats updates (active points only)

    for p in normalized:
        target = None
        # Prefer internal id if provided
        if p["id"] is not None and p["id"] in by_internal:
            target = by_internal[p["id"]]
        # Else external id if provided
        elif p["external_point_id"] is not None and p["external_point_id"] in by_external:
            target = by_external[p["external_point_id"]]

        if target is None:
            # Insert new
            new_id = p["id"] if p["id"] is not None else _gen_id("qdrant_pt")
            # Enforce unique(collection_id, external_point_id) if provided
            ext_id = p["external_point_id"] if p["external_point_id"] is not None else new_id
            if ext_id in by_external:
                # Would conflict with existing different point (shouldn't happen due to lookup above unless id provided mismatches)
                _log_request("failed", "CONFLICT", collection_id=col.get("id"))
                return _err("CONFLICT", "external_point_id already exists in collection", external_point_id=ext_id, collection_name=collection_name)

            row = {
                "id": new_id,
                "collection_id": col.get("id"),
                "external_point_id": ext_id,
                "status": "active",
                "vector": p["vector"],
                "payload": p["payload"],
                "payload_hash": _hash_payload(p["payload"]),
                "version": 1,
                "created_at": now,
                "updated_at": now,
            }
            pts.append(row)
            by_internal[new_id] = row
            by_external[ext_id] = row
            upserted += 1
            touched_active_delta += 1
        else:
            # Update existing (idempotent upsert)
            prior_status = target.get("status")
            if prior_status == "deleted":
                # Upsert restores point to active (realistic Qdrant behavior)
                target["status"] = "active"
                touched_active_delta += 1
            target["vector"] = p["vector"]
            if "payload" in p:
                target["payload"] = p["payload"]
                target["payload_hash"] = _hash_payload(p["payload"])
            # External point id can be set only if missing; do not allow changing to another value that violates uniqueness
            if p["external_point_id"] is not None and target.get("external_point_id") != p["external_point_id"]:
                if p["external_point_id"] in by_external and by_external[p["external_point_id"]].get("id") != target.get("id"):
                    _log_request("failed", "CONFLICT", collection_id=col.get("id"))
                    return _err("CONFLICT", "external_point_id already exists in collection", external_point_id=p["external_point_id"], collection_name=collection_name)
                # Update index mapping
                old_ext = target.get("external_point_id")
                if isinstance(old_ext, str) and old_ext in by_external:
                    del by_external[old_ext]
                target["external_point_id"] = p["external_point_id"]
                by_external[p["external_point_id"]] = target

            v = target.get("version")
            target["version"] = (v + 1) if isinstance(v, int) and v >= 1 else 1
            target["updated_at"] = now
            upserted += 1

    # Persist points
    _save("points.json", pts)

    # Update cached stats (eventually consistent acceptable, but we do it now)
    # Recompute for this collection to be safe.
    active_count = 0
    for p in pts:
        if isinstance(p, dict) and p.get("collection_id") == col.get("id") and p.get("status") == "active":
            active_count += 1
    col["points_count"] = active_count
    col["vectors_count"] = active_count
    col["updated_at"] = now
    _save("collections.json", cols)

    _log_request("succeeded", None, collection_id=col.get("id"))

    return {
        "result": {
            "collection_name": collection_name,
            "collection_id": col.get("id"),
            "upserted": upserted,
            "wait": wait,
        }
    }

