            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(collection_name, str) or not collection_name.strip():
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_name must be a non-empty string")
    collection_name = collection_name.strip()

    if wait is None:
        wait = True
    if not isinstance(wait, bool):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "wait must be a boolean")

    if (ids is None or ids == []) and (external_point_ids is None or external_point_ids == []):
        _log_request("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "neither ids nor external_point_ids were provided")

    if ids is not None:
        if not isinstance(ids, list) or any((not isinstance(x, str) or not x.strip()) for x in ids):
            _log_request("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "ids must be an array of non-empty strings")
        ids = [x.strip() for x in ids]

    if external_point_ids is not None:
        if not isinstance(external_point_ids, list) or any((not isinstance(x, str) or not x.strip()) for x in external_point_ids):
            _log_request("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "external_point_ids must be an array of non-empty strings")
        external_point_ids = [x.strip() for x in external_point_ids]

    cols = _load("collections.json")
    if not isinstance(cols, list):
        cols = []
    col = next((r for r in cols if isinstance(r, dict) and r.get("name") == collection_name), None)
    if not col or col.get("status") == "deleted":
        _log_request("failed", "NOT_FOUND")
        return _err("NOT_FOUND", "collection not found", collection_name=collection_name)

    pts = _load("points.json")
    if not isinstance(pts, list):
        pts = []

    now = _now_iso()
    deleted = 0

    ids_set = set(ids or [])
    ext_set = set(external_point_ids or [])

    # Mutate: active -> deleted only
    for p in pts:
        if not isinstance(p, dict):
            continue
        if p.get("collection_id") != col.get("id"):
            continue
        match = False
        if ids_set and p.get("id") in ids_set:
            match = True
        if ext_set and p.get("external_point_id") in ext_set:
            match = True
        if not match:
            continue

        if p.get("status") == "active":
            p["status"] = "deleted"
            p["updated_at"] = now
            v = p.get("version")
            p["version"] = (v + 1) if isinstance(v, int) and v >= 1 else 1
            deleted += 1
        # If already deleted, idempotent: no-op

    if deleted == 0:
        _log_request("failed", "NOT_FOUND", collection_id=col.get("id"))
        return _err("NOT_FOUND", "no matching active points found to delete", collection_name=collection_name)

    _save("points.json", pts)

    # Update cached stats
    active_count = 0
    for p in pts:
        if isinstance(p, dict) and p.get("collection_id") == col.get("id") and p.get("status") == "active":
            active_count += 1
    col["points_count"] = active_count
    col["vectors_count"] = active_count
    col["updated_at"] = now
    _save("collections.json", cols)

    _log_request("succeeded", None, collection_id=col.get("id"))

    return {
        "result": {
            "collection_name": collection_name,
            "collection_id": col.get("id"),
            "deleted": deleted,
            "wait": wait,
        }
    }

def whoami(api_key, **_extra):
    import json, os, datetime, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0415000" if __import__("os").path.isdir("./environment_mix/0415000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start_dt = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_request(status, error_code=None, credential_id=None):
        latency_ms = int((datetime.datetime.utcnow() - start_dt).total_seconds() * 1000)
        row = {
            "id": _gen_id("qdrant_req"),
            "endpoint": "whoami",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        if credential_id is not None:
            row["credential_id"] = credential_id
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(api_key, str) or not api_key.strip():
        _log_request("failed", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid credentials (api_key)")
    api_key = api_key.strip()

    # Authenticate against stored client-visible value OR id (never hashes/ciphertexts).
    candidate_files = []
    try:
        candidate_files = [fn for fn in os.listdir(_DB) if fn.endswith(".json")]
    except Exception:
        candidate_files = []

    def _match_credential_row(r):
        if not isinstance(r, dict):
            return False
        if r.get("id") == api_key:
            return True
        for k in ("api_key", "key", "value", "token", "secret"):
            v = r.get(k)
            if isinstance(v, str) and v == api_key:
                return True
        # Some stores may keep the client-visible token nested
        auth = r.get("auth")
        if isinstance(auth, dict):
            for k in ("api_key", "key", "value", "token", "secret"):
                v = auth.get(k)
                if isinstance(v, str) and v == api_key:
                    return True
        return False

    cred_row = None
    cred_file = None

    # Prefer likely filenames first, then scan all json as fallback.
    preferred = ["credentials.json", "api_keys.json", "keys.json", "auth_keys.json", "access_tokens.json", "tokens.json"]
    for fn in preferred + [f for f in candidate_files if f not in preferred]:
        path = os.path.join(_DB, fn)
        if not os.path.exists(path):
            continue
        rows = _load(fn)
        if not isinstance(rows, list):
            continue
        for r in rows:
            if _match_credential_row(r):
                cred_row = r
                cred_file = fn
                break
        if cred_row is not None:
            break

    if cred_row is None:
        _log_request("failed", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid credentials (api_key)")

    cred_id = cred_row.get("id") if isinstance(cred_row.get("id"), str) else None
    _log_request("succeeded", None, credential_id=cred_id)

    # Return whatever identity info exists; do not fabricate fields.
    result = {
        "credential": {"source": cred_file, "id": cred_id},
    }
    for k in ("account_id", "workspace_id", "user_id", "name", "scopes", "status", "created_at", "updated_at"):
        if k in cred_row:
            result["credential"][k] = cred_row.get(k)

    # Basic request log stats if present
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        used = 0
        recent_60s = 0
        now = datetime.datetime.utcnow()
        for r in logs:
            if not isinstance(r, dict):
                continue
            if cred_id is not None and r.get("credential_id") != cred_id:
                continue
            used += 1
            ts = r.get("created_at")
            if isinstance(ts, str) and ts.endswith("Z"):
                try:
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                    if (now - dt).total_seconds() <= 60:
                        recent_60s += 1
                except Exception:
                    pass
        result["usage"] = {"total_requests_logged": used, "requests_last_60s": recent_60s}

    return {"result": result}
